function canvasMap(width,height,paint,repeat=true){if(typeof document==='undefined')return null;const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;paint(canvas.getContext('2d'),width,height);const map=new THREE.CanvasTexture(canvas);map.colorSpace=THREE.SRGBColorSpace;if(repeat)map.wrapS=map.wrapT=THREE.RepeatWrapping;return map;}
function random(seed=701){return ()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
export function urbanGraffitiMap(){return canvasMap(1536,512,(c,w,h)=>{const rnd=random();c.fillStyle='#8a8981';c.fillRect(0,0,w,h);for(let n=0;n<18000;n++){c.fillStyle=n%2?'#ddd9c514':'#30363120';c.fillRect(rnd()*w,rnd()*h,1+rnd()*7,1+rnd()*3);}c.strokeStyle='#353d3955';c.lineWidth=2;for(let x=0;x<w;x+=180){c.beginPath();c.moveTo(x,0);c.lineTo(x,512);c.stroke();}for(let y=0;y<h;y+=80){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}
 const words=['RALLY','LOCAL','PLAY','ANGLE'],colors=['#d97a42','#56adad','#b695cc','#d9b553'];words.forEach((word,i)=>{const x=55+i*370,y=205+(i%2)*85;c.save();c.translate(x,y);c.rotate(i%2?-.09:.075);c.font='italic 900 96px sans-serif';c.lineJoin='round';c.strokeStyle='#283633';c.lineWidth=18;c.strokeText(word,0,0,325);c.strokeStyle='#e2d5b7';c.lineWidth=10;c.strokeText(word,0,0,325);c.fillStyle=colors[i];c.fillText(word,0,0,325);c.strokeStyle=colors[i];c.lineWidth=5;c.beginPath();c.moveTo(-4,18);c.quadraticCurveTo(170,40,330,-12);c.stroke();for(let n=0;n<11;n++){const dx=rnd()*300;c.fillRect(dx,8,2+rnd()*3,12+rnd()*60);}c.restore();});
 for(let n=0;n<160;n++){const x=rnd()*w,y=80+rnd()*340;c.fillStyle=colors[n%4]+'60';c.beginPath();c.arc(x,y,1+rnd()*4,0,Math.PI*2);c.fill();}c.font='italic 32px cursive';c.fillStyle='#30373599';for(let i=0;i<9;i++){c.save();c.translate(i*180+20,420+(i%2)*30);c.rotate(-.1);c.fillText(['KEEP PLAYING','86','SIDE SPIN'][i%3],0,0,150);c.restore();}
 c.save();c.translate(530,393);c.rotate(-.065);c.font='italic 900 46px sans-serif';c.lineJoin='round';c.strokeStyle='#263a39';c.lineWidth=9;c.strokeText('GRAY EXPECTATION',0,0,710);c.strokeStyle='#d6c9a4';c.lineWidth=4;c.strokeText('GRAY EXPECTATION',0,0,710);c.fillStyle='#79b6b2';c.fillText('GRAY EXPECTATION',0,0,710);c.strokeStyle='#79b6b2';c.lineWidth=3;c.beginPath();c.moveTo(-4,13);c.quadraticCurveTo(350,30,710,-6);c.stroke();c.restore();
 c.save();c.translate(40,380);c.rotate(.08);c.font='italic 900 42px sans-serif';c.lineJoin='round';c.strokeStyle='#382a2a';c.lineWidth=10;c.strokeText('LAFAYETTE CREW',0,0,455);c.strokeStyle='#eedfc3';c.lineWidth=5;c.strokeText('LAFAYETTE CREW',0,0,455);c.fillStyle='#822b3e';c.fillText('LAFAYETTE CREW',0,0,455);c.strokeStyle='#822b3e';c.lineWidth=3;c.beginPath();c.moveTo(-2,15);c.quadraticCurveTo(190,29,460,5);c.stroke();c.restore();
 for(let n=0;n<210;n++){c.fillStyle='#94978b77';c.fillRect(rnd()*w,rnd()*h,4+rnd()*42,1+rnd()*4);}
 });}
const APARTMENT_TILE={width:1536,height:1536,worldWidth:16.2,worldHeight:15};
function apartmentMap(windows=true){return canvasMap(APARTMENT_TILE.width,APARTMENT_TILE.height,(c,w,h)=>{const rnd=random(820);c.fillStyle='#62564a';c.fillRect(0,0,w,h);for(let y=0;y<h;y+=17)for(let x=(y/17%2)*-32;x<w;x+=64){c.fillStyle=['#955b43','#84543f','#a46649','#7e4c3d'][Math.floor(rnd()*4)];c.fillRect(x+2,y+2,61,14);c.fillStyle='#c8ae8b18';c.fillRect(x+4,y+2,52,2);}
 if(windows)for(let row=0;row<6;row++)for(let col=0;col<6;col++){const x=65+col*256,y=36+row*256;c.fillStyle='#302f2b';c.fillRect(x-8,y-10,142,194);c.fillStyle='#9a8d75';c.fillRect(x-4,y-6,134,184);const g=c.createLinearGradient(x,y,x+126,y+172);g.addColorStop(0,'#263b42');g.addColorStop(.5,'#476068');g.addColorStop(1,'#182c31');c.fillStyle=g;c.fillRect(x,y,126,172);c.fillStyle=rnd()<.2?'#d0a86966':'#baa78633';c.fillRect(x+5,y+84,116,80);c.fillStyle='#d5d1bb55';const curtain=7+rnd()*32;c.fillRect(x+9,y,curtain,169);c.fillRect(x+113-curtain,y,curtain+9,169);c.fillStyle='#26332f';c.fillRect(x+60,y,6,172);c.fillRect(x,y+80,126,7);c.fillStyle='#c9d3cc30';c.beginPath();c.moveTo(x+28,y+6);c.lineTo(x+56,y+6);c.lineTo(x+15,y+74);c.lineTo(x+5,y+74);c.fill();c.fillStyle='#b2a18a';c.fillRect(x-12,y+173,150,9);c.fillStyle='#312f2b66';c.fillRect(x-8,y+182,142,9);
 }

 // Light soot and rain streaks keep the original brick palette and silhouette.
 for(let i=0;i<95;i++){c.fillStyle=i%3?'#292a2515':'#c0ac8b13';c.fillRect(rnd()*w,rnd()*h,2+rnd()*18,25+rnd()*160);}for(let i=0;i<55;i++){const x=rnd()*w,y=Math.floor(rnd()*h/17)*17;c.strokeStyle='#b8a89340';c.lineWidth=.7;c.beginPath();c.moveTo(x,y);c.lineTo(x+30+rnd()*30,y);c.stroke();}
 });}
export function apartmentGlassMaterial(){const map=canvasMap(APARTMENT_TILE.width,APARTMENT_TILE.height,c=>{for(let row=0;row<6;row++)for(let col=0;col<6;col++){const x=65+col*256,y=36+row*256;c.fillStyle='#bfd3c980';c.fillRect(x+3,y+3,120,166);c.fillStyle='#edf0d933';c.beginPath();c.moveTo(x+18,y+6);c.lineTo(x+42,y+6);c.lineTo(x+8,y+76);c.lineTo(x+4,y+76);c.fill();}});const glass=new THREE.MeshPhysicalMaterial({color:'#b4cbc5',map,transparent:true,opacity:.24,transmission:.3,roughness:.16,thickness:.02,metalness:0,depthWrite:false,side:THREE.DoubleSide});glass.userData.playgroundApartmentGlass=true;return glass;}
export function urbanLinePaintMap(){return canvasMap(512,32,(c,w,h)=>{const rnd=random(91);c.fillStyle='#fff1b3';c.fillRect(0,0,w,h);for(let i=0;i<140;i++){c.fillStyle=i%2?'#343b37':'#7c805f';c.fillRect(rnd()*w,rnd()*h,1+rnd()*13,1+rnd()*4);}for(let x=0;x<w;x+=12){c.fillStyle='#343b37';c.fillRect(x,0,4+rnd()*6,rnd()*5);c.fillRect(x,h-rnd()*4,5+rnd()*7,4);}});}
export function setUrbanWallUV(mesh){const p=mesh.geometry?.attributes.position,uv=mesh.geometry?.attributes.uv;if(!p||!uv)return;mesh.updateWorldMatrix(true,false);const v=new THREE.Vector3(),normal=new THREE.Vector3().fromBufferAttribute(mesh.geometry.attributes.normal,0).transformDirection(mesh.matrixWorld),alongZ=Math.abs(normal.x)>Math.abs(normal.z);for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i).applyMatrix4(mesh.matrixWorld);uv.setXY(i,(alongZ?v.z:v.x)/12,v.y/3.4);}uv.needsUpdate=true;}
export const PLAYGROUND_BACKDROP={bottom:-24,top:42,extent:72,cornerOverlap:3.45,setback:3.2};
export function buildUrbanPlayground(){
 const sides=new THREE.Group(),ends=[],upper=new THREE.Group();sides.add(upper);sides.userData.urbanPlayground=true;
 const cornerBrick=finish('#b9b7a8',{map:apartmentMap(false),side:THREE.DoubleSide}),apartmentGlass=apartmentGlassMaterial(),brick=finish('#b9b7a8',{map:apartmentMap(),side:THREE.DoubleSide}),iron=finish('#687775',{metalness:.65,roughness:.68}),coping=finish('#9c9d8e'),wallMap=urbanGraffitiMap(),lineMap=urbanLinePaintMap();
 function fence(span){const g=new THREE.Group(),vertices=[],bottom=3.48,top=5.75,step=.22;for(const slope of [-1,1])for(let x=-span/2-(top-bottom);x<span/2+(top-bottom);x+=step){let y0=bottom,y1=top;const at=y=>x+slope*(y-bottom);if(slope===1){y0=Math.max(y0,bottom-span/2-x);y1=Math.min(y1,bottom+span/2-x);}else{y0=Math.max(y0,bottom+x-span/2);y1=Math.min(y1,bottom+x+span/2);}if(y1>y0)vertices.push(at(y0),y0,.045,at(y1),y1,.045);}
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));const mesh=new THREE.LineSegments(geo,new THREE.LineBasicMaterial({color:'#829491',transparent:true,opacity:.6}));mesh.userData.chainLink=true;g.add(mesh);for(let x=-span/2;x<=span/2+.01;x+=Math.max(.1,span/Math.ceil(span/3))){beam(g,[x,3.35,.04],[x,5.85,.04],.035,iron);}for(const y of [3.52,5.78])beam(g,[-span/2,y,.04],[span/2,y,.04],.032,iron);return g;
 }
 function frontage(span,height=13,extendLeft=0,extendRight=0,includeFence=true){const {bottom,top,cornerOverlap}=PLAYGROUND_BACKDROP,width=span+2*cornerOverlap+extendLeft+extendRight,centre=(extendRight-extendLeft)/2,g=new THREE.Group(),facade=new THREE.Mesh(new THREE.PlaneGeometry(width,top-bottom),brick);facade.position.set(centre,(top+bottom)/2,-1.1);facade.userData.apartmentFacade=true;facade.userData.backdropExtent={bottom,top,width};const uv=facade.geometry.attributes.uv;for(let i=0;i<uv.count;i++)uv.setXY(i,(uv.getX(i)*width+centre-width/2)/APARTMENT_TILE.worldWidth,(uv.getY(i)*(top-bottom)+bottom-3.4)/APARTMENT_TILE.worldHeight);g.add(facade);const glazing=new THREE.Mesh(facade.geometry,apartmentGlass);glazing.position.copy(facade.position);glazing.position.z+=.012;glazing.userData.apartmentGlazing=true;g.add(glazing);if(includeFence){const link=fence(span);link.userData.courtyardFence=true;g.add(link);const cap=block(g,span,.18,.32,0,3.4,0,coping);cap.userData.courtyardFence=true;}block(g,span+.15,.22,.5,0,height+.1,-1.1,coping);
 // Narrow iron fire escapes and drainpipes break up the brick frontage.
 for(let x=-span/2+1.3;x<span/2-1;x+=5.4){beam(g,[x,3.6,-.92],[x,height,-.92],.026,iron);for(let y=6.2;y<height;y+=2.6){block(g,1.5,.055,.5,x,y,-.75,iron);for(const dx of [-.67,.67])beam(g,[x+dx,y,-.5],[x+dx,y+.64,-.5],.016,iron);beam(g,[x-.67,y+.64,-.5],[x+.67,y+.64,-.5],.016,iron);}}
 // Brick-only corner bays end between complete window columns, never through glazing.
 for(const corner of [-span/2-PLAYGROUND_BACKDROP.setback,span/2+PLAYGROUND_BACKDROP.setback]){const lo=Math.floor((corner-1.8)/2.7)*2.7,hi=Math.ceil((corner+1.8)/2.7)*2.7,mask=new THREE.Mesh(new THREE.PlaneGeometry(hi-lo,top-bottom),cornerBrick);mask.position.set((lo+hi)/2,(top+bottom)/2,-1.07);mask.userData.apartmentCornerBrick={lo,hi,corner};const uv=mask.geometry.attributes.uv;for(let i=0;i<uv.count;i++)uv.setXY(i,(lo+uv.getX(i)*(hi-lo))/APARTMENT_TILE.worldWidth,(bottom+uv.getY(i)*(top-bottom)-3.4)/APARTMENT_TILE.worldHeight);g.add(mask);}
 const offset=PLAYGROUND_BACKDROP.setback-1.1;for(const child of g.children)if(!child.userData.courtyardFence)child.position.z-=offset;
 return g;
 }
 // The fence follows the playable tambour; apartments form a straight courtyard wall.
 for(const run of mainWallRuns()){const frame=wallFrame(run),span=Math.hypot(run.xb-run.xa,run.b-run.a);frame.userData.urbanTambourRun={a:run.a,b:run.b};frame.add(fence(span));block(frame,span,.18,.32,0,3.4,0,coping);upper.add(frame);}
 const right=frontage(venueRear+C.halfLength,14,PLAYGROUND_BACKDROP.extent-C.halfLength,PLAYGROUND_BACKDROP.extent-venueRear,false);right.position.set(5,0,(venueRear-C.halfLength)/2);right.rotation.y=-Math.PI/2;right.userData.straightApartments=true;upper.add(right);
 const left=frontage(venueRear+C.halfLength,12,PLAYGROUND_BACKDROP.extent-C.halfLength,PLAYGROUND_BACKDROP.extent-venueRear);left.position.set(C.roofOuterX,0,(venueRear-C.halfLength)/2);left.rotation.y=Math.PI/2;upper.add(left);
 for(const side of [-1,1]){const g=new THREE.Group(),z=side>0?venueRear:-C.halfLength,span=5-C.roofOuterX;g.userData.endSide=side;const face=frontage(span,side>0?15:13,0,0,false);face.position.set((5+C.roofOuterX)/2,0,z);face.rotation.y=side>0?Math.PI:0;g.add(face);const fenceSpan=wallX(z)-C.roofOuterX,edge=new THREE.Group();edge.add(fence(fenceSpan));block(edge,fenceSpan,.18,.32,0,3.4,0,coping);edge.position.set((wallX(z)+C.roofOuterX)/2,0,z);edge.rotation.y=side>0?Math.PI:0;g.add(edge);ends.push(g);}

 // Asphalt continues beneath the cutaway court instead of exposing background sky.
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(180,180),finish('#3e4841'));ground.rotation.x=-Math.PI/2;ground.position.y=-.35;ground.userData.playgroundGround=true;upper.add(ground);
 return {sides,ends,wallMap,lineMap,setVisible(on,overview=false){sides.visible=on;upper.visible=!overview;for(const g of ends)g.visible=on&&!overview;},setEndView(){},update(){}};
}
